PRAGMA foreign_keys=ON;
PRAGMA journal_mode=WAL;
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY, username TEXT UNIQUE COLLATE NOCASE, email TEXT UNIQUE COLLATE NOCASE, password TEXT NOT NULL, name TEXT, about TEXT DEFAULT '', status TEXT DEFAULT 'Online', custom TEXT DEFAULT '');
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY, uid INTEGER REFERENCES users, expires INTEGER);
CREATE TABLE IF NOT EXISTS spaces(id INTEGER PRIMARY KEY, name TEXT, owner INTEGER REFERENCES users, invite TEXT UNIQUE);
CREATE TABLE IF NOT EXISTS members(space INTEGER REFERENCES spaces ON DELETE CASCADE, uid INTEGER REFERENCES users, role TEXT DEFAULT 'Member', PRIMARY KEY(space,uid));
CREATE TABLE IF NOT EXISTS rooms(id INTEGER PRIMARY KEY, space INTEGER REFERENCES spaces ON DELETE CASCADE, name TEXT, kind TEXT, topic TEXT DEFAULT '', restricted INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS participants(room INTEGER REFERENCES rooms ON DELETE CASCADE, uid INTEGER REFERENCES users, PRIMARY KEY(room,uid));
CREATE TABLE IF NOT EXISTS friends(sender INTEGER REFERENCES users, target INTEGER REFERENCES users, accepted INTEGER DEFAULT 0, PRIMARY KEY(sender,target));
CREATE TABLE IF NOT EXISTS blocks(uid INTEGER, target INTEGER, PRIMARY KEY(uid,target));
CREATE TABLE IF NOT EXISTS messages(id INTEGER PRIMARY KEY, room INTEGER REFERENCES rooms ON DELETE CASCADE, uid INTEGER REFERENCES users, body TEXT, parent INTEGER REFERENCES messages ON DELETE SET NULL, time INTEGER, pinned INTEGER DEFAULT 0, edited INTEGER DEFAULT 0, file TEXT, mime TEXT, bytes BLOB);
CREATE TABLE IF NOT EXISTS thread_posts(msg INTEGER PRIMARY KEY REFERENCES messages ON DELETE CASCADE,root INTEGER REFERENCES messages ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS thread_by_root ON thread_posts(root);
CREATE INDEX IF NOT EXISTS history ON messages(room,id);
CREATE TABLE IF NOT EXISTS reactions(msg INTEGER REFERENCES messages ON DELETE CASCADE, uid INTEGER, emoji TEXT, PRIMARY KEY(msg,uid,emoji));
CREATE TABLE IF NOT EXISTS reads(room INTEGER REFERENCES rooms ON DELETE CASCADE, uid INTEGER, last INTEGER, PRIMARY KEY(room,uid));
CREATE TABLE IF NOT EXISTS bans(space INTEGER REFERENCES spaces ON DELETE CASCADE, uid INTEGER, PRIMARY KEY(space,uid));
CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY,space INTEGER REFERENCES spaces ON DELETE CASCADE,uid INTEGER,action TEXT,time INTEGER);
